async function visibleNavButton(f,target){const all=f.locator(`.nav [data-v143-dest="${target}"]`);const count=await all.count();const visible=[];for(let i=0;i<count;i++){const x=all.nth(i);if(await x.isVisible().catch(()=>false))visible.push(i)}if(visible.length!==1)throw new Error(`Expected exactly one visible nav button for ${target}; found ${visible.length} visible of ${count}`);return all.nth(visible[0])}
async function clickNav(f,target){const b=await visibleNavButton(f,target);await b.click({timeout:5000});await waitState(f,t=>window.V===t,target,5000);await f.waitForTimeout(120);return await f.evaluate(t=>({target:t,current:window.V,active:Array.from(document.querySelectorAll('.nav button.active')).filter(x=>x.offsetParent!==null).map(x=>String(x.textContent||'').trim()),text:(document.getElementById('A')?.innerText||document.body.innerText||'').slice(0,5000),updateRoot:!!document.getElementById('v146UpdatesRoot'),renderCount:window.__LTS_V146_UPDATES_RENDER_COUNT||0}),target)}

